  CONSTRAINT `org_warehouse_claims_inventory_item_id_fkey` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `org_warehouse_claims_offered_by_fkey` FOREIGN KEY (`offered_by`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `org_warehouse_claims_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `orgs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `org_warehouse_release_requests` (
