  CONSTRAINT `shop_reservations_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `orgs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `shop_reservations_warehouse_id_fkey` FOREIGN KEY (`warehouse_id`) REFERENCES `org_warehouse` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `user_blueprint_collection` (
  `user_id` CHAR(36) NOT NULL,
  `blueprint_id` CHAR(36) NOT NULL,
  `acquired_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`user_id`, `blueprint_id`),
  CONSTRAINT `user_blueprint_collection_blueprint_id_fkey` FOREIGN KEY (`blueprint_id`) REFERENCES `blueprints` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_blueprint_collection_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `user_roles` (
  `id` CHAR(36) NOT NULL,
  `user_id` CHAR(36) NOT NULL,
  `role` ENUM('admin','user') NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_roles_user_id_role_key` (`user_id`, `role`),
  CONSTRAINT `user_roles_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `user_ships` (
  `id` CHAR(36) NOT NULL,
  `user_id` CHAR(36) NOT NULL,
  `ship_slug` LONGTEXT NULL,
  `ship_name` LONGTEXT NOT NULL,
  `manufacturer` LONGTEXT NULL,
  `custom_name` LONGTEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `source` VARCHAR(255) NOT NULL DEFAULT 'manual',
  `location` LONGTEXT NULL,
  `notes` LONGTEXT NULL,
  `org_id` CHAR(36) NULL,
  PRIMARY KEY (`id`),
  KEY `user_ships_org_id_idx` (`org_id`),
  KEY `user_ships_user_source_idx` (`user_id`, `source`),
  CONSTRAINT `user_ships_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `orgs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `user_ships_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `wiki_sync_runs` (
  `id` CHAR(36) NOT NULL,
  `started_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `finished_at` DATETIME(6) NULL,
  `status` LONGTEXT NOT NULL DEFAULT 'running',
  `pages` INT NULL,
  `scanned` INT NULL,
  `inserted` INT NULL,
  `skipped` INT NULL,
  `backfilled_uex` INT NULL,
  `duration_ms` BIGINT NULL,
  `error_message` LONGTEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `wiki_sync_runs_started_idx` (`started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

SET FOREIGN_KEY_CHECKS = 1;
